private final class ListStorage {
    var items: [String]
    init(_ items: [String]) { self.items = items }
}
struct PackingList {
    private var storage: ListStorage
    init(_ items: [String]) { storage = ListStorage(items) }
    var items: [String] { storage.items }
    mutating func removeLast() -> String? {
        guard !storage.items.isEmpty else { return nil }
        if !isKnownUniquelyReferenced(&storage) {
            storage = ListStorage(storage.items)
        }
        return storage.items.popLast()
    }
    mutating func append(_ item: String) {
        if !isKnownUniquelyReferenced(&storage) {
            storage = ListStorage(storage.items)
        }
        storage.items.append(item)
    }
}
let original = PackingList(["Кроссовки", "Полотенце"])
var draft = original
print(draft.removeLast() ?? "Пусто")
print(original.items.count)
print(draft.items.count)
var empty = PackingList([])
print(empty.removeLast() == nil)

