private final class PackingStorage {
    var isPacked: Bool
    init(_ isPacked: Bool) { self.isPacked = isPacked }
}
struct PackingState {
    private var storage: PackingStorage
    init(isPacked: Bool) { storage = PackingStorage(isPacked) }
    var isPacked: Bool { storage.isPacked }
    mutating func setPacked(_ value: Bool) {
        if !isKnownUniquelyReferenced(&storage) {
            storage = PackingStorage(storage.isPacked)
        }
        storage.isPacked = value
    }
}
let original = PackingState(isPacked: false)
var draft = original
draft.setPacked(true)
print(original.isPacked)
print(draft.isPacked)

Вывод false, true. Алгоритм отделения перенесён на другой элемент состояния, а не повторён append.
